#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    long long x;
    cin >> n >> k >> x;

    vector<long long> ar(n);
    for (long long& value : ar) cin >> value;

    int used = min(n, k);
    long long ans = 1LL * used * x;

    for (int i = 0; i < n - used; ++i)
        ans += ar[i];

    cout << ans << '\n';
    return 0;
}

